    if 'DESIGNWEEK' in d: return ('business_expense','27a','Conference registration = professional development; line 27a')
    if 'MARINA DELI' in d: return ('business_expense','24b','Meal while traveling away from home on business; 50% deductible: 64.00 x 50% = 32.00 (Pub 463, line 24b)')
    if 'TARTINE' in d: return ('personal','','No documented business purpose; if a business meal -> line 24b at 50% (63.00); ask Dana')
    if 'MACBOOK' in d: return ('business_expense','27a','MacBook Pro 14, 2,149.00, expensed under de minimis safe harbor, Reg. 1.263(a)-1(f) (line 13 excerpt; <=2,500 per item); line 27a; election statement attached; 100% business use assumed - confirm')
